AND ( SQL_NM LIKE '%' || #{keyword, jdbcType=VARCHAR} || '%' OR SQL_DESC LIKE '%' || #{keyword, jdbcType=VARCHAR} || '%' OR PGM_NM LIKE '%' || #{keyword, jdbcType=VARCHAR} || '%' )
AND PGM_NM = #{pgmNm, jdbcType=VARCHAR}
ORDER BY TO_NUMBER(SQL_SEQ) DESC

